package com.hms.imports;
import com.hms.appointments.*; import com.hms.departments.*; import com.hms.doctors.*; import com.hms.services.*; import com.hms.tenancy.*; import jakarta.validation.constraints.NotNull; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/imports") public class ImportController {private final TenantRepository tenants;private final ImportJobRepository jobs;private final DepartmentRepository departments;private final DoctorRepository doctors;private final HospitalServiceRepository services;private final PatientRepository patients;public ImportController(TenantRepository t,ImportJobRepository j,DepartmentRepository d,DoctorRepository dr,HospitalServiceRepository s,PatientRepository p){tenants=t;jobs=j;departments=d;doctors=dr;services=s;patients=p;} @GetMapping public List<ImportJob> list(@PathVariable String tenantSlug){return jobs.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) public ImportJob upload(@PathVariable String tenantSlug,@RequestParam ImportType type,@RequestPart("file") @NotNull MultipartFile file){if(file.isEmpty())throw new IllegalArgumentException("Import file is empty");UUID id=tenant(tenantSlug);try{List<String> lines=new String(file.getBytes(),StandardCharsets.UTF_8).lines().toList();if(lines.size()<2)throw new IllegalArgumentException("CSV must contain a header and at least one row");String[] headers=split(lines.get(0));List<String> errors=new ArrayList<>();int imported=0,skipped=0;Set<String> seen=new HashSet<>();for(int i=1;i<lines.size();i++){if(lines.get(i).isBlank())continue;try{String[] c=split(lines.get(i));String key=c[0].trim().toLowerCase();if(!seen.add(key)){skipped++;errors.add("Row "+(i+1)+": duplicate in file");continue;}switch(type){case DEPARTMENTS->importDepartment(id,c);case DOCTORS->importDoctor(id,c);case SERVICES->importService(id,c);case PATIENTS->importPatient(id,c);}imported++;}catch(Exception e){skipped++;errors.add("Row "+(i+1)+": "+e.getMessage());}}return jobs.save(new ImportJob(id,type,lines.size()-1,imported,skipped,String.join("; ",errors)));}catch(Exception e){if(e instanceof IllegalArgumentException)throw (IllegalArgumentException)e;throw new IllegalArgumentException("Unable to read CSV import");}} private void importDepartment(UUID t,String[] c){require(c,2);if(departments.existsByTenantIdAndCode(t,c[0].trim().toUpperCase())||departments.existsByTenantIdAndName(t,c[1].trim()))throw new IllegalArgumentException("department already exists");departments.save(new Department(t,c[0].trim().toUpperCase(),c[1].trim(),value(c,2)));} private void importDoctor(UUID t,String[] c){require(c,1);doctors.save(new Doctor(t,new CreateDoctorRequest(c[0],value(c,1),null,null,number(c,2),null,null,true,Set.of())));} private void importService(UUID t,String[] c){require(c,2);services.save(new HospitalService(t,new CreateServiceRequest(c[0],c[1],value(c,2),decimal(c,3),null,true)));} private void importPatient(UUID t,String[] c){require(c,2);patients.save(new Patient(t,new CreateAppointmentRequest(c[0],c[1],value(c,2),value(c,3),UUID.randomUUID(),java.time.OffsetDateTime.now(),java.time.OffsetDateTime.now().plusMinutes(1),AppointmentSource.IMPORTED,null,null)));} private void require(String[] c,int count){if(c.length<count)throw new IllegalArgumentException("missing required columns");} private String value(String[] c,int i){return c.length>i&& !c[i].isBlank()?c[i].trim():null;} private Integer number(String[] c,int i){String v=value(c,i);return v==null?null:Integer.valueOf(v);} private BigDecimal decimal(String[] c,int i){String v=value(c,i);return v==null?null:new BigDecimal(v);} private String[] split(String line){return line.split(",",-1);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
